reset role;
set request.jwt.claim.sub='10000000-0000-4000-8000-000000000001';
insert into auth.users(id,email) values('10000000-0000-4000-8000-000000000005','escala@example.test');
insert into pieggi.usuarios(id,nome) values('10000000-0000-4000-8000-000000000005','Expedição fixture');
insert into pieggi.usuario_empresas(usuario_id,empresa_id) values('10000000-0000-4000-8000-000000000005','20000000-0000-4000-8000-000000000001');
insert into pieggi.usuario_papeis(usuario_id,papel) values('10000000-0000-4000-8000-000000000005','EXPEDICAO_COMPRAS');
do $$ declare e1 uuid;e2 uuid;p1 uuid;f uuid;pedido1 uuid:=gen_random_uuid();pedido2 uuid:=gen_random_uuid();rev integer;corpo jsonb;begin
  insert into pieggi.fornecedores(empresa_id,nome) values('20000000-0000-4000-8000-000000000001','Profissional fixture') returning id into f;
  insert into pieggi.eventos(id,empresa_id,cliente_id,titulo,liberacao_excepcional_motivo) values(gen_random_uuid(),'20000000-0000-4000-8000-000000000001','30000000-0000-4000-8000-000000000001','Escala um','Fixture') returning id into e1;
  insert into pieggi.eventos(id,empresa_id,cliente_id,titulo,liberacao_excepcional_motivo) values(gen_random_uuid(),'20000000-0000-4000-8000-000000000001','30000000-0000-4000-8000-000000000001','Escala dois','Fixture') returning id into e2;
  insert into pieggi.programacoes(evento_id,empresa_id,versao,status,saida_em,itens,alteracoes,criado_por)
    select id,empresa_id,1,'APROVADA',now(),'[{"nome":"Caprese","quantidade":10,"unidade":"UN","setor":"COZINHA_FRIA","receita":"Completa"}]','Fixture escala','10000000-0000-4000-8000-000000000001' from pieggi.eventos where id in(e1,e2);
  select id into p1 from pieggi.programacoes where evento_id=e1;
  set role authenticated;
  perform pieggi.operar_equipe(e1,1,'VERBA','{"limite":200}');
  perform pieggi.operar_equipe(e2,1,'VERBA','{"limite":200}');
  select revisao into rev from pieggi.eventos where id=e1;
  corpo:=jsonb_build_object('id',pedido1,'fornecedorId',f,'categoria','EQUIPE','funcao','Líder de montagem','inicio','2026-10-06T12:00:00-03:00','fim','2026-10-06T16:00:00-03:00','orientacoes','Mesa principal');
  perform pieggi.operar_equipe(e1,rev,'SOLICITAR',corpo);
  perform pieggi.operar_equipe(e1,rev,'SOLICITAR',corpo);
  if (select count(*) from pieggi.evento_equipe where evento_id=e1)<>1 then raise exception 'TESTE: solicitação duplicou';end if;
  select revisao into rev from pieggi.eventos where id=e1;
  begin perform pieggi.operar_equipe(e1,rev,'APROVAR',jsonb_build_object('id',pedido1,'valor',201,'referencia','Cotação teste'));raise exception 'TESTE: estourou verba';exception when raise_exception then if SQLERRM<>'Verba não definida ou insuficiente. Ajuste a alçada financeira antes de aprovar.' then raise;end if;end;
  perform pieggi.operar_equipe(e1,rev,'APROVAR',jsonb_build_object('id',pedido1,'valor',150.25,'referencia','Cotação teste'));
  select revisao into rev from pieggi.eventos where id=e2;
  perform pieggi.operar_equipe(e2,rev,'SOLICITAR',corpo||jsonb_build_object('id',pedido2));
  select revisao into rev from pieggi.eventos where id=e2;
  begin perform pieggi.operar_equipe(e2,rev,'APROVAR',jsonb_build_object('id',pedido2,'valor',100,'referencia','Cotação teste'));raise exception 'TESTE: dupla reserva aceita';exception when raise_exception then if SQLERRM<>'Profissional já reservado neste horário. Ajuste a escala.' then raise;end if;end;
  select revisao into rev from pieggi.eventos where id=e1;
  perform pieggi.operar_equipe(e1,rev,'CONFIRMAR',jsonb_build_object('id',pedido1,'referencia','Aceite teste'));
  select revisao into rev from pieggi.eventos where id=e1;
  perform pieggi.operar_equipe(e1,rev,'REALIZAR',jsonb_build_object('id',pedido1,'referencia','Prestação conferida','competencia',current_date));
  begin perform pieggi.operar_equipe(e1,rev,'REALIZAR',jsonb_build_object('id',pedido1,'referencia','Prestação conferida','competencia',current_date));raise exception 'TESTE: repetiu execução';exception when serialization_failure then null;end;
  if (select count(*) from pieggi.evento_custos where idempotencia=pedido1)<>1 or (select valor from pieggi.evento_custos where idempotencia=pedido1)<>150.25 then raise exception 'TESTE: despesa incorreta/duplicada';end if;
  select revisao into rev from pieggi.eventos where id=e2;
  perform pieggi.operar_equipe(e2,rev,'APROVAR',jsonb_build_object('id',pedido2,'valor',100,'referencia','Cotação teste'));
  reset role;
  update pieggi.programacoes set status='INVALIDADA' where evento_id=e2;
  if (select estado from pieggi.evento_equipe where id=pedido2)<>'A_REVISAR' then raise exception 'TESTE: escala antiga não bloqueou';end if;
  set role authenticated;
  select revisao into rev from pieggi.eventos where id=e2;
  begin perform pieggi.operar_equipe(e2,rev,'VERBA','{"limite":50}');raise exception 'TESTE: revisão liberou reserva financeira';exception when raise_exception then if SQLERRM<>'A verba não pode ser menor que as contratações já aprovadas.' then raise;end if;end;
  set request.jwt.claim.sub='10000000-0000-4000-8000-000000000005';
  if not exists(select 1 from pieggi.evento_equipe where id=pedido2) then raise exception 'TESTE: expedição não vê escala';end if;
  if exists(select 1 from pieggi.equipe_valores) or exists(select 1 from pieggi.evento_verbas) then raise exception 'TESTE: valores vazaram para operação';end if;
  select revisao into rev from pieggi.eventos where id=e2;
  begin perform pieggi.operar_equipe(e2,rev,'VERBA','{"limite":1000}');raise exception 'TESTE: operação aprovou verba';exception when insufficient_privilege then null;end;
end $$;
reset role;
